CREATE DATABASE IF NOT EXISTS careconnect CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE careconnect;
CREATE TABLE IF NOT EXISTS users (
 id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,phone VARCHAR(40) NOT NULL UNIQUE,
 password VARCHAR(255) NOT NULL,role ENUM('customer','provider','admin') NOT NULL,address VARCHAR(255) DEFAULT '',dob DATE NULL,
 session_version INT UNSIGNED NOT NULL DEFAULT 0,avatar VARCHAR(80) DEFAULT 'design-imgPhotoRahim.svg',invite_code VARCHAR(32) UNIQUE,active BOOLEAN NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS categories(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,description VARCHAR(255) NOT NULL,icon VARCHAR(50) NOT NULL,rate DECIMAL(10,2) NOT NULL,active BOOLEAN DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS provider_profiles(user_id INT PRIMARY KEY,category_id INT NOT NULL,verification ENUM('Pending','Under Review','Approved','Rejected','Suspended') DEFAULT 'Pending',experience INT DEFAULT 0,qualification VARCHAR(255) DEFAULT '',bio TEXT,rate DECIMAL(10,2) DEFAULT 500,availability VARCHAR(255) DEFAULT '',document_name VARCHAR(255) NULL,document_data MEDIUMBLOB NULL,document_mime VARCHAR(80) NULL,rejection_reason VARCHAR(255) DEFAULT '',FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(category_id) REFERENCES categories(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS family_links(id INT AUTO_INCREMENT PRIMARY KEY,family_id INT NOT NULL,elder_id INT NOT NULL,status ENUM('Pending','Approved','Rejected') DEFAULT 'Pending',UNIQUE(family_id,elder_id),FOREIGN KEY(family_id) REFERENCES users(id),FOREIGN KEY(elder_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS bookings(id INT AUTO_INCREMENT PRIMARY KEY,requester_id INT NOT NULL,elder_id INT NOT NULL,provider_id INT NOT NULL,category_id INT NOT NULL,service_date DATE NOT NULL,start_time TIME NOT NULL,duration INT NOT NULL,address VARCHAR(255) NOT NULL,notes TEXT,status VARCHAR(30) DEFAULT 'Pending',rate DECIMAL(10,2) NOT NULL,total DECIMAL(10,2) NOT NULL,payment_status ENUM('Unpaid','Paid') DEFAULT 'Unpaid',completion_notes TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(requester_id) REFERENCES users(id),FOREIGN KEY(elder_id) REFERENCES users(id),FOREIGN KEY(provider_id) REFERENCES users(id),FOREIGN KEY(category_id) REFERENCES categories(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS status_history(id INT AUTO_INCREMENT PRIMARY KEY,booking_id INT NOT NULL,status VARCHAR(30) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(booking_id) REFERENCES bookings(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS contacts(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,name VARCHAR(120) NOT NULL,relationship VARCHAR(80) NOT NULL,phone VARCHAR(40) NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS notifications(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,message VARCHAR(500) NOT NULL,is_read BOOLEAN DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS sos_alerts(id INT AUTO_INCREMENT PRIMARY KEY,elder_id INT NOT NULL,latitude DECIMAL(10,7) NULL,longitude DECIMAL(10,7) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(elder_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS reviews(id INT AUTO_INCREMENT PRIMARY KEY,booking_id INT NOT NULL UNIQUE,user_id INT NOT NULL,rating INT NOT NULL,review TEXT,FOREIGN KEY(booking_id) REFERENCES bookings(id),FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS complaints(id INT AUTO_INCREMENT PRIMARY KEY,booking_id INT NOT NULL,user_id INT NOT NULL,message TEXT NOT NULL,status ENUM('Open','Resolved') DEFAULT 'Open',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(booking_id) REFERENCES bookings(id),FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS audit_logs(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,message VARCHAR(500) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS login_attempts(identity_hash CHAR(64) PRIMARY KEY,attempts INT DEFAULT 0,last_attempt DATETIME NOT NULL) ENGINE=InnoDB;
